INSERT INTO article_blocks (article_id, position, type, payload, anchor)
SELECT a.id, 13, 'rich_list',
       $b1390${"ordered":false,"items":[{"title":"Десктопные кошельки","text":"Устанавливаются на ПК или ноутбук. Примеры: Exodus, Electrum, Atomic Wallet. Часто обладают расширенной функциональностью (включая обмен криптовалют внутри интерфейса, управление NFT и токенами, подключение к аппаратным кошелькам);"},{"title":"Мобильные кошельки","text":"Приложения для Android и iOS. Примеры: Trust Wallet, Coinomi, Mycelium, SafePal. Удобны для повседневного использования, быстрой оплаты и P2P-переводов;"},{"title":"Веб-кошельки (браузерные)","text":"Работают через веб-интерфейс. Примеры: Blockchain.com, MetaMask, Binance Wallet. Не требуют установки, работают на любом устройстве с браузером;"},{"title":"Биржевые кошельки","text":"Связаны с аккаунтом на централизованной бирже. Примеры: Binance, Bybit, OKX, KuCoin. Подходят для активной торговли, но не предоставляют контроль над приватными ключами."}]}$b1390$::jsonb,
