INSERT INTO article_blocks (article_id, position, type, payload, anchor)
SELECT a.id, 76, 'pros_cons',
       $b1453${"pros":["Бесплатное использование;","Поддержка основных сетей, включая BTC и SOL;","Хранение приватных ключей на стороне пользователя;","Возможность работы с NFT-активами;","Наличие функции стейкинга;","Максимально простой и дружелюбный интерфейс;","Анонимность при работе с криптовалютой;","Есть поддержка русского языка."],"cons":["Работа ограничена использованием мобильной версии;","Отсутствие двухфакторной идентификации;","Нет поддержки DApps;","Так как платформа принадлежит Binance, перспективы работы на российском рынке остаются непонятными."]}$b1453$::jsonb,
