INSERT INTO article_blocks (article_id, position, type, payload, anchor)
SELECT a.id, 85, 'paragraph',
       $b1462${"text":"Однако для хранения крупных сумм стоит рассматривать комбинированную стратегию: горячий кошелек – для повседневных операций, а холодный – для сбережений.","html":"Однако для хранения крупных сумм стоит рассматривать комбинированную стратегию: горячий кошелек – для повседневных операций, а холодный – для сбережений."}$b1462$::jsonb,
       NULL
FROM articles a WHERE a.slug = 'kakoj-koshelek-dlya-kriptovalyuty-vybrat-10-luchshih-goryachih-hranilishh';

INSERT INTO article_blocks (article_id, position, type, payload, anchor)
SELECT a.id, 86, 'paragraph',
       $b1463${"text":"Идеальный подход: разделение риска и грамотное управление безопасностью. Только так можно воспользоваться преимуществами цифровых активов без страха потери средств.","html":"Идеальный подход: разделение риска и грамотное управление безопасностью. Только так можно воспользоваться преимуществами цифровых активов без страха потери средств."}$b1463$::jsonb,
